function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 50) return 'grid needs 1 to 50 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 cells.';
  let buildings = 0;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    for (const v of row) {
      if (v !== 0 && v !== 1 && v !== 2) return 'Each cell is 0, 1 or 2.';
      if (v === 1) buildings++;
    }
  }
  if (buildings === 0) return 'The grid needs at least one building.';
  return null;
}

