function shortestDistance(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const total = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const reach = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const moves = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let buildings = 0;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== 1) continue;
      buildings++;
      const seen = Array.from({ length: rows }, () => new Array(cols).fill(false));
      let queue = [[r, c]];
      let distance = 0;
      while (queue.length > 0) {
        distance++;
        const next = [];
        for (const [row, col] of queue) {
          for (const [dr, dc] of moves) {
            const nr = row + dr;
            const nc = col + dc;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (grid[nr][nc] !== 0 || seen[nr][nc]) continue;
            seen[nr][nc] = true;
            total[nr][nc] += distance;
            reach[nr][nc]++;
            next.push([nr, nc]);
          }
        }
        queue = next;
      }
    }
  }

  let best = Infinity;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 0 && reach[r][c] === buildings) {
        best = Math.min(best, total[r][c]);
      }
    }
  }
  return best === Infinity ? -1 : best;
}

