function shortestDistance(grid) {
  // For every open cell, relax distances repeatedly (Bellman-Ford style) until nothing changes.
  const m = grid.length, n = grid[0].length;
  let best = -1;
  for (let sr = 0; sr < m; sr++) for (let sc = 0; sc < n; sc++) {
    if (grid[sr][sc] !== 0) continue;
    const d = grid.map(row => row.map(() => Infinity));
    d[sr][sc] = 0;
    let changed = true;
    while (changed) {
      changed = false;
      for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
        if (grid[r][c] === 2) continue;
        for (const [pr, pc] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
          if (pr < 0 || pc < 0 || pr >= m || pc >= n || grid[pr][pc] !== 0) continue;
          if (d[pr][pc] + 1 < d[r][c]) { d[r][c] = d[pr][pc] + 1; changed = true; }
        }
      }
    }
    let sum = 0, ok = true;
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
      if (grid[r][c] !== 1) continue;
      if (d[r][c] === Infinity) ok = false; else sum += d[r][c];
    }
    if (ok && (best === -1 || sum < best)) best = sum;
  }
  return best;
}

