function generate(rand, size) {
  const large = size === 'large';
  const m = large ? (rand() < 0.7 ? 50 : 20 + Math.floor(rand() * 31)) : 1 + Math.floor(rand() * 5);
  const n = large ? (rand() < 0.7 ? 50 : 20 + Math.floor(rand() * 31)) : 1 + Math.floor(rand() * 5);
  const pBuilding = large ? 0.01 + rand() * 0.05 : 0.1 + rand() * 0.3;
  const pObstacle = large ? rand() * 0.2 : rand() * 0.3;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => {
    const x = rand();
    return x < pBuilding ? 1 : x < pBuilding + pObstacle ? 2 : 0;
  }));
  if (!grid.some(row => row.includes(1))) grid[Math.floor(rand() * m)][Math.floor(rand() * n)] = 1;
  return [grid];
}
